(function () {
  var root = document.getElementById('schedule');
  if (!root) return;
  var tabs = Array.prototype.slice.call(root.querySelectorAll('.day-tab'));
  var panels = Array.prototype.slice.call(root.querySelectorAll('.day-panel'));
  function show(day, focus) {
    tabs.forEach(function (t) {
      var on = t.getAttribute('data-day') === day;
      t.setAttribute('aria-selected', on ? 'true' : 'false');
      t.setAttribute('tabindex', on ? '0' : '-1');
      if (on && focus) t.focus();
    });
    panels.forEach(function (p) {
      if (p.getAttribute('data-day') === day) p.removeAttribute('hidden');
      else p.setAttribute('hidden', '');
    });
  }
  tabs.forEach(function (t, i) {
    t.addEventListener('click', function () { show(t.getAttribute('data-day'), false); });
    t.addEventListener('keydown', function (e) {
      var n = null;
      if (e.key === 'ArrowRight') n = (i + 1) % tabs.length;
      else if (e.key === 'ArrowLeft') n = (i - 1 + tabs.length) % tabs.length;
      if (n !== null) { e.preventDefault(); show(tabs[n].getAttribute('data-day'), true); }
    });
  });
  show('1', false);
})();
